INSERT INTO chat_sdk_lists VALUES('msg-history:telegram:8641420749',904,'{"_type":"chat:Message","id":"8641420749:2043","threadId":"telegram:8641420749","text":"Je sens que j’ai plus mal a la cheville ce soir après le velo, malgré y etre allé tranquille aujourd’hui, comme j’ai eu plus mal apres la rampa dimanche. Donc il faut certainement que je calme un peu le velo malheureusement…\nJe peux faire qqch ce soir ? Un anti inflammatoire ? Ou autre ?","formatted":{"type":"root","children":[{"type":"paragraph","children":[{"type":"text","value":"Je sens que j’ai plus mal a la cheville ce soir après le velo, malgré y etre allé tranquille aujourd’hui, comme j’ai eu plus mal apres la rampa dimanche. Donc il faut certainement que je calme un peu le velo malheureusement…\nJe peux faire qqch ce soir ? Un anti inflammatoire ? Ou autre ?","position":{"start":{"line":1,"column":1,"offset":0},"end":{"line":2,"column":64,"offset":288}}}],"position":{"start":{"line":1,"column":1,"offset":0},"end":{"line":2,"column":64,"offset":288}}}],"position":{"start":{"line":1,"column":1,"offset":0},"end":{"line":2,"column":64,"offset":288}}},"raw":null,"author":{"userId":"8641420749","userName":"Clément","fullName":"Clément de Coligny","isBot":false,"isMe":false},"metadata":{"dateSent":"2026-10-13T22:23:04.000Z","edited":false},"attachments":[],"isMention":false}',1792534984087);
INSERT INTO chat_sdk_lists VALUES('msg-history:telegram:8641420749',905,'{"_type":"chat:Message","id":"8641420749:2046","threadId":"telegram:8641420749","text":"Baume du tigre ca peut aider sur la cheville ?","formatted":{"type":"root","children":[{"type":"paragraph","children":[{"type":"text","value":"Baume du tigre ca peut aider sur la cheville ?","position":{"start":{"line":1,"column":1,"offset":0},"end":{"line":1,"column":47,"offset":46}}}],"position":{"start":{"line":1,"column":1,"offset":0},"end":{"line":1,"column":47,"offset":46}}}],"position":{"start":{"line":1,"column":1,"offset":0},"end":{"line":1,"column":47,"offset":46}}},"raw":null,"author":{"userId":"8641420749","userName":"Clément","fullName":"Clément de Coligny","isBot":false,"isMe":false},"metadata":{"dateSent":"2026-10-13T22:46:46.000Z","edited":false},"attachments":[],"isMention":false}',1792536406668);
INSERT INTO chat_sdk_lists VALUES('msg-history:telegram:8641420749',906,'{"_type":"chat:Message","id":"8641420749:2047","threadId":"telegram:8641420749","text":"J’ai pas de glace","formatted":{"type":"root","children":[{"type":"paragraph","children":[{"type":"text","value":"J’ai pas de glace","position":{"start":{"line":1,"column":1,"offset":0},"end":{"line":1,"column":18,"offset":17}}}],"position":{"start":{"line":1,"column":1,"offset":0},"end":{"line":1,"column":18,"offset":17}}}],"position":{"start":{"line":1,"column":1,"offset":0},"end":{"line":1,"column":18,"offset":17}}},"raw":null,"author":{"userId":"8641420749","userName":"Clément","fullName":"Clément de Coligny","isBot":false,"isMe":false},"metadata":{"dateSent":"2026-10-13T22:46:53.000Z","edited":false},"attachments":[],"isMention":false}',1792536413468);
INSERT INTO chat_sdk_lists VALUES('msg-history:telegram:8641420749',907,'{"_type":"chat:Message","id":"8641420749:2050","threadId":"telegram:8641420749","text":"C’est confirmé, c’est une entorse legere, un etirement leger du ligament de la cheville. \nPrends en compte quand c’est arrivé, ce que j’ai fait depuis, et mets en place un plan de recuperation avec des exercices spécifiques ainsi que la reprise progressive du sport. Mets en place des tests d’évaluation récurrent pour voir où j’en suis depuis la recup. Dis moi s’il te manque des infos ou si tu penses qu’on oublie qqch","formatted":{"type":"root","children":[{"type":"paragraph","children":[{"type":"text","value":"C’est confirmé, c’est une entorse legere, un etirement leger du ligament de la cheville.\nPrends en compte quand c’est arrivé, ce que j’ai fait depuis, et mets en place un plan de recuperation avec des exercices spécifiques ainsi que la reprise progressive du sport. Mets en place des tests d’évaluation récurrent pour voir où j’en suis depuis la recup. Dis moi s’il te manque des infos ou si tu penses qu’on oublie qqch","position":{"start":{"line":1,"column":1,"offset":0},"end":{"line":2,"column":331,"offset":420}}}],"position":{"start":{"line":1,"column":1,"offset":0},"end":{"line":2,"column":331,"offset":420}}}],"position":{"start":{"line":1,"column":1,"offset":0},"end":{"line":2,"column":331,"offset":420}}},"raw":null,"author":{"userId":"8641420749","userName":"Clément","fullName":"Clément de Coligny","isBot":false,"isMe":false},"metadata":{"dateSent":"2026-10-14T08:58:51.000Z","edited":false},"attachments":[],"isMention":false}',1792573130858);
INSERT INTO chat_sdk_lists VALUES('msg-history:telegram:8641420749',908,'{"_type":"chat:Message","id":"8641420749:911","threadId":"telegram:8641420749","text":"Je suis en train d''effectuer une estimation du cout de la vie a Madrid a niveau de vie equivalent pour septembre 2027. Pour ca j''ai besoin d''un rapport de nos depenses mensuelles communes par categorie, de la plus importante a la moins importante. Je vais faire cette estimation avec un autre agent. Ajoute les notes suivantes : aujourd''hui on ne paye l''ecole que pour 1 enfant (creche feliz) mais en septembre 2027 on payerait pour 2 enfants. Notre loyer actuel est 1.5 a 2x en dessous du prix du marché.","formatted":{"type":"root","children":[{"type":"paragraph","children":[{"type":"text","value":"Je suis en train d''effectuer une estimation du cout de la vie a Madrid a niveau de vie equivalent pour septembre 2027. Pour ca j''ai besoin d''un rapport de nos depenses mensuelles communes par categorie, de la plus importante a la moins importante. Je vais faire cette estimation avec un autre agent. Ajoute les notes suivantes : aujourd''hui on ne paye l''ecole que pour 1 enfant (creche feliz) mais en septembre 2027 on payerait pour 2 enfants. Notre loyer actuel est 1.5 a 2x en dessous du prix du marché.","position":{"start":{"line":1,"column":1,"offset":0},"end":{"line":1,"column":506,"offset":505}}}],"position":{"start":{"line":1,"column":1,"offset":0},"end":{"line":1,"column":506,"offset":505}}}],"position":{"start":{"line":1,"column":1,"offset":0},"end":{"line":1,"column":506,"offset":505}}},"raw":null,"author":{"userId":"8641420749","userName":"Clément","fullName":"Clément de Coligny","isBot":false,"isMe":false},"metadata":{"dateSent":"2026-10-14T10:41:34.000Z","edited":false},"attachments":[],"isMention":false}',1792579294364);
INSERT INTO chat_sdk_lists VALUES('msg-history:telegram:8641420749',909,'{"_type":"chat:Message","id":"8641420749:915","threadId":"telegram:8641420749","text":"Inclue aussi nos salaires mensuelles tout compris (1000eur/an de ticket creche, remboursement IRS etc...). Le but etant d''estimer combien on peut economiser et investir chaque mois avec nos niveaux de vie actuelles (en sept 2027) a Madrid et comparer a nos economies en vivant a Lisbonne.","formatted":{"type":"root","children":[{"type":"paragraph","children":[{"type":"text","value":"Inclue aussi nos salaires mensuelles tout compris (1000eur/an de ticket creche, remboursement IRS etc...). Le but etant d''estimer combien on peut economiser et investir chaque mois avec nos niveaux de vie actuelles (en sept 2027) a Madrid et comparer a nos economies en vivant a Lisbonne.","position":{"start":{"line":1,"column":1,"offset":0},"end":{"line":1,"column":289,"offset":288}}}],"position":{"start":{"line":1,"column":1,"offset":0},"end":{"line":1,"column":289,"offset":288}}}],"position":{"start":{"line":1,"column":1,"offset":0},"end":{"line":1,"column":289,"offset":288}}},"raw":null,"author":{"userId":"8641420749","userName":"Clément","fullName":"Clément de Coligny","isBot":false,"isMe":false},"metadata":{"dateSent":"2026-10-14T10:50:09.000Z","edited":false},"attachments":[],"isMention":false}',1792579808696);
