INSERT INTO chat_sdk_lists VALUES('msg-history:telegram:8641420749',914,'{"_type":"chat:Message","id":"8641420749:2053","threadId":"telegram:8641420749","text":"Je vais voir le kiné, quelles questions poser ?","formatted":{"type":"root","children":[{"type":"paragraph","children":[{"type":"text","value":"Je vais voir le kiné, quelles questions poser ?","position":{"start":{"line":1,"column":1,"offset":0},"end":{"line":1,"column":48,"offset":47}}}],"position":{"start":{"line":1,"column":1,"offset":0},"end":{"line":1,"column":48,"offset":47}}}],"position":{"start":{"line":1,"column":1,"offset":0},"end":{"line":1,"column":48,"offset":47}}},"raw":null,"author":{"userId":"8641420749","userName":"Clément","fullName":"Clément de Coligny","isBot":false,"isMe":false},"metadata":{"dateSent":"2026-10-14T15:04:12.000Z","edited":false},"attachments":[],"isMention":false}',1792595050970);
INSERT INTO chat_sdk_lists VALUES('msg-history:telegram:8641420749',915,'{"_type":"chat:Message","id":"8641420749:2056","threadId":"telegram:8641420749","text":"Bilan du physio : il a fait plusieurs manubulations dans tous les mouvements possibles. Je n''ai pas de douleur spéciale en mouvement, uniquement une douleur très spécifique en appuyant sur un point très précis du ligament. Donc c''est bien une petite entorse legere. Il a confirmé avec une échographie \n\nOn a fait un traitement EPI. Il m''a dit de ne pas m''entraîner aujourd''hui ni demain. Après-demain je peux reprendre et je contrôle toute la douleur. Si j''ai mal, j''arrête. Je continue le renfort que je fais d''habitude, y compris le traitement des pieds, qui ne peut faire qu''aider. On refait un EPI dans une semaine","formatted":{"type":"root","children":[{"type":"paragraph","children":[{"type":"text","value":"Bilan du physio : il a fait plusieurs manubulations dans tous les mouvements possibles. Je n''ai pas de douleur spéciale en mouvement, uniquement une douleur très spécifique en appuyant sur un point très précis du ligament. Donc c''est bien une petite entorse legere. Il a confirmé avec une échographie","position":{"start":{"line":1,"column":1,"offset":0},"end":{"line":1,"column":301,"offset":300}}}],"position":{"start":{"line":1,"column":1,"offset":0},"end":{"line":1,"column":302,"offset":301}}},{"type":"paragraph","children":[{"type":"text","value":"On a fait un traitement EPI. Il m''a dit de ne pas m''entraîner aujourd''hui ni demain. Après-demain je peux reprendre et je contrôle toute la douleur. Si j''ai mal, j''arrête. Je continue le renfort que je fais d''habitude, y compris le traitement des pieds, qui ne peut faire qu''aider. On refait un EPI dans une semaine","position":{"start":{"line":3,"column":1,"offset":303},"end":{"line":3,"column":316,"offset":618}}}],"position":{"start":{"line":3,"column":1,"offset":303},"end":{"line":3,"column":316,"offset":618}}}],"position":{"start":{"line":1,